import JSZip from 'jszip';

const SHEET_NS = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main';
const REL_NS = 'http://schemas.openxmlformats.org/package/2006/relationships';
const OFFICE_REL_NS = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships';
const CONTENT = 'application/vnd.openxmlformats-officedocument.spreadsheetml';

export const SHEET_FIXTURE_PARTS = {
  workbook: 'xl/workbook.xml',
  data: 'xl/worksheets/sheet1.xml',
  summary: 'xl/worksheets/sheet2.xml',
  styles: 'xl/styles.xml',
  strings: 'xl/sharedStrings.xml',
  calcChain: 'xl/calcChain.xml',
  table: 'xl/tables/table1.xml',
  custom: 'customXml/item1.xml',
} as const;

/**
 * An independently written workbook with the structures real files carry: shared strings with
 * rich and phonetic runs, a shared formula, a table, merges, a frozen header, custom widths and
 * heights, theme colors, a calculation chain and parts the editor never displays.
 */
export async function makeSheetFixture(overrides: Partial<Record<string, string>> = {}): Promise<Uint8Array> {
  const parts: Record<string, string> = {
    '[Content_Types].xml': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="${CONTENT}.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="${CONTENT}.worksheet+xml"/><Override PartName="/xl/worksheets/sheet2.xml" ContentType="${CONTENT}.worksheet+xml"/><Override PartName="/xl/theme/theme1.xml" ContentType="application/vnd.openxmlformats-officedocument.theme+xml"/><Override PartName="/xl/styles.xml" ContentType="${CONTENT}.styles+xml"/><Override PartName="/xl/sharedStrings.xml" ContentType="${CONTENT}.sharedStrings+xml"/><Override PartName="/xl/calcChain.xml" ContentType="${CONTENT}.calcChain+xml"/><Override PartName="/xl/tables/table1.xml" ContentType="${CONTENT}.table+xml"/></Types>`,
    '_rels/.rels': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="${REL_NS}"><Relationship Id="rId1" Type="${OFFICE_REL_NS}/officeDocument" Target="xl/workbook.xml"/></Relationships>`,
    'xl/workbook.xml': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="${SHEET_NS}" xmlns:r="${OFFICE_REL_NS}"><workbookPr defaultThemeVersion="164011"/><bookViews><workbookView xWindow="0" yWindow="0" windowWidth="28800" windowHeight="12300" activeTab="0"/></bookViews><sheets><sheet name="数据" sheetId="1" r:id="rId1"/><sheet name="Summary" sheetId="2" r:id="rId2"/></sheets><definedNames><definedName name="Rate">Summary!$B$1</definedName><definedName name="_xlnm.Print_Area" localSheetId="0">数据!$A$1:$E$6</definedName></definedNames><calcPr calcId="191029"/></workbook>`,
    'xl/_rels/workbook.xml.rels': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="${REL_NS}"><Relationship Id="rId1" Type="${OFFICE_REL_NS}/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="${OFFICE_REL_NS}/worksheet" Target="/xl/worksheets/sheet2.xml"/><Relationship Id="rId3" Type="${OFFICE_REL_NS}/theme" Target="theme/theme1.xml"/><Relationship Id="rId4" Type="${OFFICE_REL_NS}/styles" Target="styles.xml"/><Relationship Id="rId5" Type="${OFFICE_REL_NS}/sharedStrings" Target="sharedStrings.xml"/><Relationship Id="rId6" Type="${OFFICE_REL_NS}/calcChain" Target="calcChain.xml"/></Relationships>`,
    'xl/theme/theme1.xml': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><a:theme xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" name="Office"><a:themeElements><a:clrScheme name="Office"><a:dk1><a:sysClr val="windowText" lastClr="000000"/></a:dk1><a:lt1><a:sysClr val="window" lastClr="FFFFFF"/></a:lt1><a:dk2><a:srgbClr val="44546A"/></a:dk2><a:lt2><a:srgbClr val="E7E6E6"/></a:lt2><a:accent1><a:srgbClr val="4472C4"/></a:accent1><a:accent2><a:srgbClr val="ED7D31"/></a:accent2><a:accent3><a:srgbClr val="A5A5A5"/></a:accent3><a:accent4><a:srgbClr val="FFC000"/></a:accent4><a:accent5><a:srgbClr val="5B9BD5"/></a:accent5><a:accent6><a:srgbClr val="70AD47"/></a:accent6><a:hlink><a:srgbClr val="0563C1"/></a:hlink><a:folHlink><a:srgbClr val="954F72"/></a:folHlink></a:clrScheme></a:themeElements></a:theme>`,
    'xl/styles.xml': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="${SHEET_NS}"><numFmts count="1"><numFmt numFmtId="164" formatCode="0.0%"/></numFmts><fonts count="2"><font><sz val="11"/><color theme="1"/><name val="Calibri"/><family val="2"/><scheme val="minor"/></font><font><b/><sz val="12"/><color rgb="FFC00000"/><name val="Calibri"/><family val="2"/><scheme val="minor"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor theme="4" tint="0.79998168889431442"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="2"><border><left/><right/><top/><bottom/><diagonal/></border><border><left style="thin"><color indexed="64"/></left><right style="thin"><color indexed="64"/></right><top style="thin"><color indexed="64"/></top><bottom style="thin"><color indexed="64"/></bottom><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="5"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="2" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1"><alignment horizontal="center"/></xf><xf numFmtId="14" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/><xf numFmtId="164" fontId="0" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyBorder="1"><alignment vertical="center" wrapText="1"/><protection locked="0"/></xf><xf numFmtId="4" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles><dxfs count="0"/></styleSheet>`,
    'xl/sharedStrings.xml': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><sst xmlns="${SHEET_NS}" count="7" uniqueCount="7"><si><t>项目</t></si><si><t>数量</t></si><si><t>金额</t></si><si><t>苹果</t></si><si><r><rPr><b/></rPr><t>香</t></r><r><t xml:space="preserve">蕉 </t></r><rPh sb="0" eb="1"><t>xiang</t></rPh></si><si><t>line1_x000D_
line2</t></si><si><t>合计</t></si></sst>`,
    'xl/worksheets/sheet1.xml': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="${SHEET_NS}" xmlns:r="${OFFICE_REL_NS}"><sheetPr><tabColor rgb="FF00B050"/></sheetPr><dimension ref="A1:E6"/><sheetViews><sheetView tabSelected="1" zoomScale="90" workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/><selection pane="bottomLeft" activeCell="A2" sqref="A2"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight="15"/><cols><col min="1" max="1" width="18.7109375" customWidth="1"/><col min="2" max="3" width="12.7109375" customWidth="1"/><col min="5" max="5" width="9.140625" hidden="1"/></cols><sheetData><row r="1" spans="1:5" ht="21" customHeight="1"><c r="A1" s="1" t="s"><v>0</v></c><c r="B1" s="1" t="s"><v>1</v></c><c r="C1" s="1" t="s"><v>2</v></c><c r="E1" s="3"/></row><row r="2" spans="1:5"><c r="A2" t="s"><v>3</v></c><c r="B2"><v>3</v></c><c r="C2" s="4"><f>B2*Rate</f><v>15</v></c><c r="D2" t="b"><v>1</v></c></row><row r="3" spans="1:5"><c r="A3" t="s"><v>4</v></c><c r="B3"><v>4</v></c><c r="C3" s="4"><f t="shared" ref="C3:C4" si="0">B3*Rate</f><v>20</v></c><c r="D3" s="2"><v>46293</v></c></row><row r="4" spans="1:5" hidden="1"><c r="A4" t="s"><v>5</v></c><c r="B4"><v>5</v></c><c r="C4" s="4"><f t="shared" si="0"/><v>25</v></c><c r="D4" s="3"><v>0.256</v></c></row><row r="6"><c r="A6" t="s"><v>6</v></c><c r="B6"><f>SUM(B2:B4)</f><v>12</v></c><c r="C6" t="inlineStr"><is><t>备注 &amp; note</t></is></c></row></sheetData><mergeCells count="1"><mergeCell ref="D6:E6"/></mergeCells><conditionalFormatting sqref="B2:B4"><cfRule type="cellIs" dxfId="0" priority="1" operator="greaterThan"><formula>3</formula></cfRule></conditionalFormatting><pageMargins left="0.7" right="0.7" top="0.75" bottom="0.75" header="0.3" footer="0.3"/><tableParts count="1"><tablePart r:id="rId1"/></tableParts></worksheet>`,
    'xl/worksheets/_rels/sheet1.xml.rels': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="${REL_NS}"><Relationship Id="rId1" Type="${OFFICE_REL_NS}/table" Target="../tables/table1.xml"/></Relationships>`,
    'xl/tables/table1.xml': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><table xmlns="${SHEET_NS}" id="1" name="Fruit" displayName="Fruit" ref="A1:C4" totalsRowShown="0"><autoFilter ref="A1:C4"/><tableColumns count="3"><tableColumn id="1" name="项目"/><tableColumn id="2" name="数量"/><tableColumn id="3" name="金额"/></tableColumns><tableStyleInfo name="TableStyleMedium2" showFirstColumn="0" showLastColumn="0" showRowStripes="1" showColumnStripes="0"/></table>`,
    'xl/worksheets/sheet2.xml': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="${SHEET_NS}"><dimension ref="A1:B2"/><sheetViews><sheetView showGridLines="0" workbookViewId="0"/></sheetViews><sheetFormatPr defaultRowHeight="15"/><sheetData><row r="1"><c r="A1" t="str"><f>"Rate"</f><v>Rate</v></c><c r="B1"><v>5</v></c></row><row r="2"><c r="A2"><f>数据!B6*2</f><v>24</v></c></row></sheetData><pageMargins left="0.7" right="0.7" top="0.75" bottom="0.75" header="0.3" footer="0.3"/></worksheet>`,
    'xl/calcChain.xml': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><calcChain xmlns="${SHEET_NS}"><c r="C2" i="1"/><c r="C3" i="1"/><c r="C4" i="1"/><c r="B6" i="1"/><c r="A1" i="2"/><c r="A2" i="2"/></calcChain>`,
    'customXml/item1.xml': '<custom xmlns="urn:lobster:test">preserve me verbatim</custom>',
    ...overrides,
  };
  const zip = new JSZip();
  for (const [name, contents] of Object.entries(parts)) if (contents !== undefined) zip.file(name, contents);
  return zip.generateAsync({ type: 'uint8array', compression: 'DEFLATE' });
}
